530:   if((os->e_o_s&&os->lacing_fill) ||          /* 'were done, now flush' case */
531:      (os->lacing_fill&&!os->b_o_s))           /* 'initial header page' case */
532:     force=1;
533: 
534:   return(ogg_stream_flush_i(os,og,force,nfill));
535: }
